import{_ as t,o,c as a,a5 as s}from"./chunks/framework.DukzBDYY.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/troubleshooting.md","filePath":"getting-started/troubleshooting.md"}'),r={name:"getting-started/troubleshooting.md"};function h(i,e,n,l,d,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="no-slots-show-at-checkout" tabindex="-1">No slots show at checkout <a class="header-anchor" href="#no-slots-show-at-checkout" aria-label="Permalink to &quot;No slots show at checkout&quot;">​</a></h2><ul><li><strong>Is the schedule on?</strong> In <strong>Delivery Slots → Schedules</strong>, the method should show <strong>On</strong> and have at least one window.</li><li><strong>Is the method chosen?</strong> <code>cart.deliverySlotDays</code> uses the cart’s shipping method. Before one is chosen, pass a handle: <code>cart.getDeliverySlotDays(&#39;localDelivery&#39;)</code>.</li><li><strong>Does the schedule have zones?</strong> Then only addresses inside one get slots. Check the cart has a shipping address (or an estimated one) that’s inside a zone.</li><li><strong>Is every day unavailable?</strong> Each day has an <code>unavailableReason</code>, such as <em>Closed</em>, <em>Not in your area</em> or <em>Ordering has closed</em>. Show it in your template to see why.</li></ul><h2 id="the-shipping-method-has-disappeared" tabindex="-1">The shipping method has disappeared <a class="header-anchor" href="#the-shipping-method-has-disappeared" aria-label="Permalink to &quot;The shipping method has disappeared&quot;">​</a></h2><p>A method whose schedule has zones isn’t offered to addresses outside every zone. That’s deliberate, so customers can’t order delivery you don’t make. Add a zone for the area, or remove the method’s zones to deliver anywhere its shipping rules allow.</p><h2 id="choose-a-delivery-time-when-paying" tabindex="-1">“Choose a delivery time” when paying <a class="header-anchor" href="#choose-a-delivery-time-when-paying" aria-label="Permalink to &quot;“Choose a delivery time” when paying&quot;">​</a></h2><p>The method has slots and the order has none, or the one it had is full. Customers see this as an error on <code>cart.getFirstError(&#39;deliverySlot&#39;)</code>. Show it on your payment page and link back to the shipping step.</p><h2 id="that-delivery-time-is-no-longer-available" tabindex="-1">“That delivery time is no longer available” <a class="header-anchor" href="#that-delivery-time-is-no-longer-available" aria-label="Permalink to &quot;“That delivery time is no longer available”&quot;">​</a></h2><p>The slot filled up, closed (its cut-off or notice passed) or doesn’t exist, such as a slot posted from an old tab. The cart isn’t updated, and the customer can choose again.</p><h2 id="slot-times-are-an-hour-out" tabindex="-1">Slot times are an hour out <a class="header-anchor" href="#slot-times-are-an-hour-out" aria-label="Permalink to &quot;Slot times are an hour out&quot;">​</a></h2><p>Check the site’s time zone in <strong>Settings → General</strong>. Slot times are in that time zone.</p><h2 id="the-run-sheet-is-empty" tabindex="-1">The run sheet is empty <a class="header-anchor" href="#the-run-sheet-is-empty" aria-label="Permalink to &quot;The run sheet is empty&quot;">​</a></h2><p>The run sheet shows completed orders. Carts that are still checking out hold slots, but aren’t on it. Check the date and shipping method at the top of the page.</p>',13)])])}const m=t(r,[["render",h]]);export{p as __pageData,m as default};
